static void hci_num_comp_pkts_evt(struct hci_dev *hdev, void *data,
					  u8 event, u8 *param, int param_len)
{
	struct hci_num_comp_pkts_evt *ev = (void *)param;
	int i;

	bt_dev_dbg(hdev, "num %d", ev->num);

	hci_dev_lock(hdev);

	for (i = 0; i < ev->num; i++) {
		struct hci_comp_pkts_info *info = &ev->handles[i];
		struct hci_conn *conn;

		if (!info->handle)
			continue;

		conn = hci_conn_hash_lookup_handle(hdev, info->handle);
		if (!conn)
			continue;

		bt_dev_dbg(hdev, "handle 0x%2.2x num_pkts %d",
			   info->handle, info->num_pkts);

		hci_conn_tx_dequeue(conn, info->num_pkts);
	}

	queue_work(hdev->workqueue, &hdev->tx_work);

	hci_dev_unlock(hdev);
}
